class Sensor {
private:
    int id;
    std::string unit;
    float value;
public:
    Sensor(int i, std::string u, float v) : id(i), unit(u), value(v) {}
    void printInfo() const {
        std::cout << "Sensor " << id << ": " << value << " " << unit << "\n";
    }
};

int main() {
    Sensor s1(1, "°C", 22.5f);
    Sensor s2(2, "%RH", 41.0f);
    s1.printInfo();
    s2.printInfo();
}
